const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const makePanel = (tag, title, firstWord, accent) => {
  const panel = document.createElement("div");
  panel.className = "mo-card mo-p-panel" + (accent ? " mo-p-accent" : "");
  const caption = document.createElement("p");
  caption.className = "mo-caption mo-p-tag";
  caption.textContent = tag;
  const heading = document.createElement("h2");
  heading.className = "mo-p-title";
  heading.textContent = title;
  const list = document.createElement("ul");
  list.className = "mo-p-rows";
  const rows = [0, 1].map((offset) => {
    const row = document.createElement("li");
    row.className = "mo-p-row";
    const mark = document.createElement("span");
    mark.className = "mo-p-mark";
    row.append(mark, document.createTextNode(wordsFrom(firstWord + offset * 2, 2)));
    list.append(row);
    return row;
  });
  panel.append(caption, heading, list);
  return { panel, rows };
};
const split = document.createElement("div");
split.className = "mo-split";
const left = makePanel("Before", "The old way", 0, false);
const right = makePanel("After", "The new way", 4, true);
split.append(left.panel, right.panel);
ctx.root.append(split);
const fromX = ctx.aspect === "16:9" ? 60 : 0;
const fromY = ctx.aspect === "16:9" ? 0 : 50;
ctx.timeline.from(left.panel, { opacity: 0, x: -fromX, y: fromY, duration: 0.6, ease: "power3.out" }, cue(0.05));
ctx.timeline.from(right.panel, { opacity: 0, x: fromX, y: fromY, duration: 0.6, ease: "power3.out" }, cue(0.5));
left.rows.forEach((row, index) => {
  ctx.timeline.from(row, { opacity: 0, x: -24, duration: 0.4, ease: "power2.out" }, cue(0.15 + index * 0.15));
});
right.rows.forEach((row, index) => {
  ctx.timeline.from(row, { opacity: 0, x: -24, duration: 0.4, ease: "power2.out" }, cue(0.6 + index * 0.15));
});

