.mo-s-{{sceneId}} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-p-panel {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: calc(var(--mo-unit) * 2);
  text-align: left;
}
.mo-s-{{sceneId}} .mo-p-title {
  margin: 0;
  font-size: var(--mo-text-subtitle);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.mo-s-{{sceneId}} .mo-p-tag {
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.mo-s-{{sceneId}} .mo-p-rows {
  display: flex;
  flex-direction: column;
  gap: calc(var(--mo-unit) * 1.4);
  margin: 0;
  padding: 0;
  list-style: none;
}
.mo-s-{{sceneId}} .mo-p-row {
  display: flex;
  gap: calc(var(--mo-unit) * 1.6);
  align-items: center;
  font-size: var(--mo-text-body);
  line-height: 1.25;
  color: var(--mo-text-secondary);
}
.mo-s-{{sceneId}} .mo-p-mark {
  flex: none;
  width: calc(var(--mo-unit) * 1.4);
  height: calc(var(--mo-unit) * 1.4);
  border-radius: 999px;
  background: var(--mo-text-muted);
}
.mo-s-{{sceneId}} .mo-p-accent {
  border-color: var(--mo-accent);
}
.mo-s-{{sceneId}} .mo-p-accent .mo-p-mark {
  background: var(--mo-success);
}
